  ('UCAT', 'Decision Making', 'Which best describes probabilistic reasoning?', '["Assuming all outcomes are equally certain","Making decisions with no data at all","Ignoring probability in decisions","Estimating the likelihood of an outcome based on available information"]'::jsonb, 3),
  ('UCAT', 'Decision Making', 'A ''trade-off'' in decision making refers to:', '["Giving up one benefit to gain another","Choosing the option with zero risk","Having no consequences to a decision","Ignoring alternative choices"]'::jsonb, 0),
  ('UCAT', 'Decision Making', 'Which of the following is a component of good logical reasoning?', '["Assuming the first idea is always correct","Relying only on gut feeling","Ensuring conclusions are supported by valid premises","Ignoring contradictory evidence"]'::jsonb, 2),
  ('UCAT', 'Decision Making', 'In interpreting data tables, it''s important to:', '["Check units and labels carefully before drawing conclusions","Assume all numbers are percentages","Guess values not explicitly given","Ignore the table headers"]'::jsonb, 0),
  ('UCAT', 'Decision Making', 'Which best supports a well-reasoned recommendation?', '["Choosing based on personal preference only","Ignoring any risks involved","Avoiding a decision altogether","Clearly weighing pros and cons based on the evidence available"]'::jsonb, 3),
  ('UCAT', 'Quantitative Reasoning', 'UCAT Quantitative Reasoning mainly tests:', '["Memory recall","Numerical reasoning and problem solving under time pressure","Verbal fluency","Essay writing"]'::jsonb, 1),
  ('UCAT', 'Quantitative Reasoning', 'What is 15% of 80?', '["8","15","10","12"]'::jsonb, 3),
  ('UCAT', 'Quantitative Reasoning', 'What is 25% of 160?', '["40","45","35","30"]'::jsonb, 0),
  ('UCAT', 'Quantitative Reasoning', 'If a train travels 240 km in 4 hours, what is its average speed?', '["70 km/h","60 km/h","50 km/h","80 km/h"]'::jsonb, 1),
  ('UCAT', 'Quantitative Reasoning', 'What is the ratio of 15 to 45 in simplest form?', '["2:3","3:1","1:2","1:3"]'::jsonb, 3),
  ('UCAT', 'Quantitative Reasoning', 'If an item costs 8,000 CFA after a 20% discount, what was its original price?', '["9,000 CFA","8,800 CFA","9,600 CFA","10,000 CFA"]'::jsonb, 3),
  ('UCAT', 'Quantitative Reasoning', 'What is the value of 3/5 of 200?', '["100","90","120","150"]'::jsonb, 2),
  ('UCAT', 'Quantitative Reasoning', 'A rectangle has an area of 48 and a width of 6. What is its length?', '["6","8","12","10"]'::jsonb, 1),
  ('UCAT', 'Quantitative Reasoning', 'What is 60 as a percentage of 240?', '["30%","20%","15%","25%"]'::jsonb, 3),
  ('UCAT', 'Quantitative Reasoning', 'If x : y = 2 : 3 and x = 10, what is y?', '["20","18","15","12"]'::jsonb, 2),
  ('UCAT', 'Situational Judgement', 'UCAT Situational Judgement measures a candidate''s:', '["Physical stamina","Understanding of appropriate behaviour in professional scenarios","Mathematical skill","Reading speed"]'::jsonb, 1),
  ('UCAT', 'Situational Judgement', 'A colleague asks you to cover a shift last minute due to a family emergency. The most appropriate response is to:', '["Report them for asking","Ignore the request entirely","Refuse without explanation","Try to help if possible, or suggest an alternative solution"]'::jsonb, 3),
  ('UCAT', 'Situational Judgement', 'If you notice a colleague making a repeated error that could affect client safety, the most appropriate action is to:', '["Publicly criticize them in front of others","Ignore it since it''s not your job","Raise the concern respectfully with the colleague or a supervisor","Say nothing to avoid conflict"]'::jsonb, 2),
  ('UCAT', 'Situational Judgement', 'A team member takes credit for your idea in a meeting. The most professional response is to:', '["Calmly clarify your contribution afterward or in the moment appropriately","Retaliate by taking credit for their future work","Say nothing and feel resentful indefinitely","Publicly confront them angrily"]'::jsonb, 0),
  ('UCAT', 'Situational Judgement', 'You are running late for an important appointment due to unforeseen circumstances. The best action is to:', '["Arrive without any explanation","Blame someone else for the delay","Simply not show up","Contact the relevant party as soon as possible to inform them"]'::jsonb, 3),
  ('UCAT', 'Situational Judgement', 'A situation requires you to keep a colleague''s personal information confidential. You should:', '["Post about it on social media","Share it if asked casually by others","Respect their privacy and not share the information","Discuss it openly in the break room"]'::jsonb, 2),
  ('UCAT', 'Situational Judgement', 'If you disagree with a supervisor''s decision, the most professional approach is to:', '["Refuse to cooperate at all","Complain to other colleagues instead","Ignore instructions and do your own thing","Respectfully share your perspective through appropriate channels"]'::jsonb, 3),
  ('UCAT', 'Situational Judgement', 'A new team member seems overwhelmed with their workload. An appropriate response is to:', '["Offer support or guidance where appropriate","Ignore their struggle entirely","Criticize their pace publicly","Take over all of their work without discussion"]'::jsonb, 0),
  ('UCAT', 'Situational Judgement', 'You receive conflicting instructions from two supervisors. The best approach is to:', '["Complain without seeking clarification","Guess which instruction to follow","Seek clarification from both to resolve the conflict","Ignore both instructions"]'::jsonb, 2),
  ('UCAT', 'Situational Judgement', 'If you make a mistake at work that affects a colleague, the most appropriate response is to:', '["Blame someone else","Ignore the consequences","Hide the mistake","Acknowledge the mistake and take steps to correct it"]'::jsonb, 3)
) as v(test_name, subject_name, question_text, options, correct_index)
join tests t on t.name = v.test_name
join subjects sub on sub.test_id = t.id and sub.name = v.subject_name
where not exists (
  select 1 from questions q
  where q.subject_id = sub.id and q.question_text = v.question_text
);
